const runFilterMatch=p=>!f.workflow||relWorkflows(p).some(w=>w.id===f.workflow||String(w.run)===f.workflow);
const qIncludes=(s,q)=>String(s??'').toLowerCase().includes(q.toLowerCase());
const prMatches=p=>{
 if(f.semantic&&!p.fixtureIds?.some(id=>data.fixtures.some(x=>x.id===id&&x.group===f.semantic)))return false;
 if(f.repo&&p.repo!==f.repo)return false;
 if(f.pr&&p.id!==f.pr)return false;
 if(f.backend&&p.backend!==f.backend&&p.backend!=='Multi-backend')return false;
 if(!runFilterMatch(p))return false;
 if(f.fixture&&!p.fixtureIds?.includes(f.fixture))return false;
 if(f.layout&&!p.layout?.includes(f.layout))return false;
 if(f.evidence&&p.class!==f.evidence&&!relWorkflows(p).some(w=>workflowClass(w)===f.evidence))return false;
 if(f.gate&&p.gate!==f.gate)return false;
 if(f.from&&(!p.updated||p.updated.slice(0,10)<f.from))return false;
 if(f.to&&(!p.updated||p.updated.slice(0,10)>f.to))return false;
 if(f.search&&!qIncludes([p.repo,p.pr,p.title,p.head,p.tree,p.backend,p.note,p.gate].join(' '),f.search))return false;
 return true;
};
