 if(f.evidence&&!x.prs.some(i=>byId(i)?.class===f.evidence||relWorkflows(byId(i)).some(w=>workflowClass(w)===f.evidence)))return false;
 if(f.from&&!x.prs.some(i=>byId(i)?.updated?.slice(0,10)>=f.from))return false;
