function renderIntro(){const m={overview:['Engineering overview','Make evidence impossible to misread.','A single operating picture for five backends, exact-head CI and defensible merge gates.'],prs:['Pull request registry','Every change. Every head. Every gate.','Track draft state, provenance, reviewer requests and current execution blockers.'],ledger:['Execution ledger','Follow the evidence, not the conclusion.','Runner admission, host tools and compiler-backed guest proof remain separate.'],fixtures:['Coverage atlas','One .atto corpus. Five backends.','Authored fixtures are not executed fixtures. See the exact missing execution boundary.'],parity:['Backend parity','Claims are not conformance.','A conservative matrix of what is authored, host-only or still unproven.'],layouts:['LRU layout lab','Choose a memory shape deliberately.','AoS, SoA and AoSoA layout contracts in lru-cache-atto/lru-cache.atto.'],bindings:['Binding semantics','Immutable by default. Precise by design.','Compare three equivalent declarations, explicit let rebinding and independent mut referent permissions.'],integrity:['Integrity & provenance','Trust the exact tree, not the badge.','Mechanical local checks, immutable pins, adversarial mutations and receipt requirements.'],queue:['Action queue','Unblock the highest-value proof first.','Prioritized hardening and native guest parity work, with concrete acceptance criteria.'],checklists:['Reusable checklists','Turn process into a repeatable gate.','Locally tracked review templates; checking a box does not produce CI evidence.']}[view];el('currentCrumb').textContent=m[0];el('viewIntro').innerHTML=`<div class="page-head"><div><div class="eyebrow"><span class="eyeline"></span> ATTO / ENGINEERING OPERATIONS</div><h1>${m[1]}</h1><p>${m[2]}</p></div><div class="snapshot-pill"><strong>● SNAPSHOT · ${esc(data.snapshot||'UNKNOWN')}</strong><small>Selected GitHub metadata · Manual updates</small></div></div>`;}
const field=(key,label,extra='')=>{let options=dataFilterOptions[key]?.()||[];return `<div class="field"><label for="flt-${key}">${label}</label><select id="flt-${key}" data-filter="${key}"><option value="">All ${label.toLowerCase()}</option>${options.map(([v,t])=>`<option value="${esc(v)}" ${f[key]===v?'selected':''}>${esc(t)}</option>`).join('')}</select></div>`;};
