function fixtureCell(fix,backend){if(fix.evidence==='SPEC_ONLY')return badge('Spec only','dim');let related=fix.prs.map(byId).filter(Boolean);let docs=related.filter(p=>p.backend===backend||p.backend==='Multi-backend');if(backend==='Java / GraalVM'&&fix.group==='LRU cache'&&related.some(p=>p.repo.startsWith('lru-cache-atto/')))return badge('Host oracle','blue');if(!docs.length)return badge('Unproven','dim');if(fix.group==='Wasm admission')return backend==='Wasm'?badge('Local host','blue'):badge('Unproven','dim');if(fix.group==='File-system contract')return badge('Contract','purple');if(backend==='Forge / Cranelift'&&fix.group==='Macros')return badge('Denial authored','purple');return badge('Authored','orange');}
