function renderParity(){const rows=data.parity.filter(x=>{
 if(f.semantic&&x.category!==f.semantic&&!x.related.some(id=>byId(id)?.fixtureIds?.some(fid=>data.fixtures.some(y=>y.id===fid&&y.group===f.semantic))))return false;
 if(f.search&&!qIncludes([x.feature,x.cases,x.category].join(' '),f.search))return false;
 if(f.fixture&&!x.related.some(id=>byId(id)?.fixtureIds.includes(f.fixture)))return false;
 if(f.pr&&!x.related.includes(f.pr))return false;
 if(f.repo&&!x.related.some(id=>byId(id)?.repo===f.repo))return false;
 if(f.layout&&!x.related.some(id=>byId(id)?.layout?.includes(f.layout)))return false;
 if(f.evidence&&!x.related.some(id=>byId(id)?.class===f.evidence))return false;
 if(f.gate&&!x.related.some(id=>byId(id)?.gate===f.gate))return false;
 if(f.workflow&&!x.related.some(id=>byId(id)?.workflowIds?.includes(f.workflow)))return false;
 if(f.from&&!x.related.some(id=>{const d=byId(id)?.updated?.slice(0,10);return d&&d>=f.from;}))return false;
 if(f.to&&!x.related.some(id=>{const d=byId(id)?.updated?.slice(0,10);return d&&d<=f.to;}))return false;
 return true;});
 el('view').innerHTML=`<div class="warning"><div class="warning-icon">≠</div><div><strong>Authored ≠ executed ≠ parity</strong><p>Every cell here remains below compiler-backed guest certification. "Host-only" reflects the executed reference/toolchain boundary; "Contract only" is a normative assertion with no executed backend proof. The matrix does not merge positive and negative proof into one badge.</p></div></div>${panel('Five-backend conformance matrix',`${rows.length} feature contracts · grouped execution states`,`<div class="parity-wrap"><table class="table parity-table"><thead><tr><th>Feature & fixture contract</th>${BACKENDS.map(b=>`<th>${esc(b)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><td><div class="record-name">${esc(r.feature)}</div><div class="record-sub">${esc(r.cases)}</div></td>${BACKENDS.map(b=>`<td>${badge(r.states[b]||'Unproven',r.states[b]==='Host-only'?'blue':r.states[b]==='Authored'?'orange':r.states[b].includes('Contract')||r.states[b].includes('Denial')?'purple':'dim')}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="matrix-key">${badge('Authored','orange')} ${badge('Host-only','blue')} ${badge('Contract only','purple')} ${badge('Unproven','dim')} ${badge('Guest verified','green')}<span class="small-ttl">Green only with real, pinned compiler + guest receipts.</span></div>`)}`;}
function drawLayout(l){let fields=l.fields;if(l.id==='SoA')return ['keys','values','live'].map((row,i)=>`<div style="margin-bottom:14px"><div class="small-ttl" style="margin-bottom:5px">${row}[]</div><div class="cell-row">${Array.from({length:5},(_,j)=>`<span class="cell ${['key','value','live'][i]}">${row==='keys'?'k'+j:row==='values'?'v'+j:(j%2?'0':'1')}</span>`).join('')}</div></div>`).join('');
 if(l.id==='AoSoA')return [0,1].map((t)=>`<div><div class="small-ttl" style="margin-bottom:7px">TILE ${t} · W=4</div>${['keys','values','live'].map((row,i)=>`<div class="cell-row" style="margin-bottom:4px">${Array.from({length:4},(_,j)=>`<span class="cell tile ${['key','value','live'][i]}">${t&&j>0?'∅':row==='keys'?'k'+(t*4+j):row==='values'?'v'+(t*4+j):'1'}</span>`).join('')}</div>`).join('')}</div>`).join('');
 return Array.from({length:3},(_,slot)=>`<div><div class="small-ttl" style="margin-bottom:7px">SLOT ${slot}</div><div class="cell-row">${fields.map((x,i)=>`<span class="cell ${x==='key'?'key':x==='value'?'value':x==='live'?'live':'pad'}">${x==='key'?'k'+slot:x==='value'?'v'+slot:x==='live'?'1':'0'}</span>`).join('')}</div></div>`).join('');}
